function t(path,fallback){var value=path.split(".").reduce(function(current,part){return current&&Object.prototype.hasOwnProperty.call(current,part)?current[part]:undefined;},TEXT);return value===undefined?fallback:value;}function fmt(template,values){return String(template).replace(/\{(\w+)\}/g,function(_,key){return values&&key in values?values[key]:_;});}
function Rng(seed){this.state=(Number(seed)>>>0)||0x9E3779B9;this.level=0;}Rng.prototype.next=function(){var x=this.state;x^=x<<13;x^=x>>>17;x^=x<<5;this.state=x>>>0;return this.state;};Rng.prototype.int=function(a,b){return a+(this.next()%(b-a+1));};Rng.prototype.pick=function(v){var limit=this.level?Math.min(v.length,Math.max(2,Math.ceil(v.length*this.level/5))):v.length;return v[this.int(0,limit-1)];};Rng.prototype.bool=function(){return Boolean(this.next()&1);};Rng.prototype.shuffle=function(v){var a=v.slice();for(var i=a.length-1;i>0;i-=1){var j=this.int(0,i),x=a[i];a[i]=a[j];a[j]=x;}return a;};
var FAMILIES=FAMILY_ROWS.map(function(row){return{id:row[0],categoryId:row[1],title:row[2],levels:(row[5]||LEVELS).slice(),learn:{concept:"Practice "+row[2].toLowerCase()+" under the exact offline "+MODEL_ID+" model.",rules:row[3],example:row[4]}};});function localizeStatic(){CATEGORIES.forEach(function(c){var x=t("categories."+c.id,null);if(x)c.title=x;});FAMILIES.forEach(function(f){var title=t("families."+f.id,null),rule=t("familyRules."+f.id,null),example=t("familyExamples."+f.id,null);if(title)f.title=title;if(rule)f.learn.rules=rule;if(example)f.learn.example=example;if(TEXT.localeCode!=="en")f.learn.concept=fmt(t("learn.familyConcept","Öva {family} enligt modellen linear-algebra-v1."),{family:f.title.toLocaleLowerCase("sv-SE")});});}localizeStatic();function familyById(id){return FAMILIES.find(function(f){return f.id===id;})||FAMILIES[0];}function categoryById(id){return CATEGORIES.find(function(c){return c.id===id;})||CATEGORIES[0];}

function tableBlock(caption,columns,rows){return{kind:"table",caption:caption,columns:columns,rows:rows};}function codeBlock(text){return{kind:"code",text:text};}function noteBlock(text){return{kind:"note",text:text};}function choice(id,label,answer,options){return{id:id,label:label,kind:"choice",answer:String(answer),options:options.map(function(x){return{value:String(x[0]),label:String(x[1])};})};}function typed(id,label,answer,kind){return{id:id,label:label,kind:kind,answer:String(answer)};}function yn(value){return choice("answer",t("fieldLabels.answer","Answer"),value?"yes":"no",[["yes",t("generated.choices.yes","Yes")],["no",t("generated.choices.no","No")]]);}function candidate(answer,values,label){var field=candidateInOrder(answer,values,label);field.shuffle=true;return field;}function shuffleCandidateFields(fields,r){fields.forEach(function(f){if(!f.shuffle||f.kind!=="choice")return;var seenLabels=new Set();f.options=f.options.filter(function(o){if(seenLabels.has(o.label)&&o.value!==f.answer)return false;seenLabels.add(o.label);return true;});var correct=f.options.filter(function(o){return o.value===f.answer;})[0].label,labels=r.shuffle(f.options.map(function(o){return o.label;}));f.options=labels.map(function(label,i){return{value:"v"+i,label:label};});f.answer="v"+labels.indexOf(correct);delete f.shuffle;});}function candidateInOrder(answer,values,label){var unique=[],seen=new Set();[answer].concat(values).forEach(function(x){var k=String(x);if(!seen.has(k)){seen.add(k);unique.push(k);}});return choice("answer",label||t("fieldLabels.answer","Answer"),"v0",unique.map(function(x,i){return["v"+i,x];}));}function ex(prompt,blocks,fields,signature,meta){return{title:t("generated.prompts."+prompt,"Choose the exact answer."),blocks:blocks,note:"",fields:fields,signature:signature,meta:meta||{}};}function seq(values){return values.join(" · ");}



