function scenario(id,level,r){r.level=0;if(!Object.prototype.hasOwnProperty.call(NGEN,id))return null;var g,tries=0;do{g=NGEN[id](level,r);}while(g.retry&&++tries<25);delete g.retry;return g;}

// ---------- Exact rationals (BigInt) ----------
function bgcd(a,b){a=a<0n?-a:a;b=b<0n?-b:b;while(b){var t=a%b;a=b;b=t;}return a;}
function R(n,d){n=BigInt(n);d=d===undefined?1n:BigInt(d);if(d===0n)throw new Error("zero denominator");if(d<0n){n=-n;d=-d;}var g=bgcd(n,d)||1n;return{n:n/g,d:d/g};}
var R0=R(0),R1=R(1);
function radd(a,b){return R(a.n*b.d+b.n*a.d,a.d*b.d);}function rsub(a,b){return R(a.n*b.d-b.n*a.d,a.d*b.d);}function rmul(a,b){return R(a.n*b.n,a.d*b.d);}function rdiv(a,b){if(b.n===0n)throw new Error("divide by zero");return R(a.n*b.d,a.d*b.n);}function rneg(a){return R(-a.n,a.d);}
function req(a,b){return a.n===b.n&&a.d===b.d;}function rz(a){return a.n===0n;}function rcmp(a,b){var x=a.n*b.d-b.n*a.d;return x<0n?-1:x>0n?1:0;}
function rstr(a){var s=a.d===1n?String(a.n):a.n+"/"+a.d;return s.replace(/^-/,"−");}
function rnum(a){return Number(a.n)/Number(a.d);}
function ri(x){return R(x);}
// ---------- Vectors and matrices over Q ----------
function V_(arr){return arr.map(function(x){return typeof x==="object"?x:R(x);});}
function M_(rows){return rows.map(V_);}
function vadd(u,v){return u.map(function(x,i){return radd(x,v[i]);});}function vsub(u,v){return u.map(function(x,i){return rsub(x,v[i]);});}function vscale(c,v){return v.map(function(x){return rmul(c,x);});}
function dot(u,v){return u.reduce(function(s,x,i){return radd(s,rmul(x,v[i]));},R0);}
function vz(v){return v.every(rz);}
function mT(A){return A[0].map(function(_,j){return A.map(function(row){return row[j];});});}
function mmul(A,B){return A.map(function(row){return B[0].map(function(_,j){return row.reduce(function(s,x,k){return radd(s,rmul(x,B[k][j]));},R0);});});}
function mvec(A,x){return A.map(function(row){return dot(row,x);});}
function madd(A,B){return A.map(function(r,i){return vadd(r,B[i]);});}function msub(A,B){return A.map(function(r,i){return vsub(r,B[i]);});}function mscale(c,A){return A.map(function(r){return vscale(c,r);});}
function ident(n){return range(n).map(function(i){return range(n).map(function(j){return i===j?R1:R0;});});}
function mcopy(A){return A.map(function(r){return r.slice();});}
function rref(A,ncols){var M=mcopy(A),m=M.length,n=ncols===undefined?M[0].length:ncols,piv=[],r=0;for(var c=0;c<n&&r<m;c+=1){var p=-1;for(var i=r;i<m;i+=1)if(!rz(M[i][c])){p=i;break;}if(p<0)continue;var t=M[p];M[p]=M[r];M[r]=t;var inv=rdiv(R1,M[r][c]);M[r]=vscale(inv,M[r]);for(var k=0;k<m;k+=1)if(k!==r&&!rz(M[k][c]))M[k]=vsub(M[k],vscale(M[k][c],M[r]));piv.push(c);r+=1;}return{R:M,piv:piv};}
function rank(A){return rref(A).piv.length;}
function det(A){var M=mcopy(A),n=M.length,d=R1;for(var c=0;c<n;c+=1){var p=-1;for(var i=c;i<n;i+=1)if(!rz(M[i][c])){p=i;break;}if(p<0)return R0;if(p!==c){var t=M[p];M[p]=M[c];M[c]=t;d=rneg(d);}d=rmul(d,M[c][c]);for(var k=c+1;k<n;k+=1)if(!rz(M[k][c])){var f=rdiv(M[k][c],M[c][c]);M[k]=vsub(M[k],vscale(f,M[c]));}}return d;}
function inverse(A){var n=A.length,aug=A.map(function(r,i){return r.concat(ident(n)[i]);}),o=rref(aug,n);if(o.piv.length<n)return null;return o.R.map(function(r){return r.slice(n);});}
// Nullspace basis from RREF: one vector per free column, with that free variable = 1.
