function runSelfTests(){var failures=[];function assert(condition,message){if(!condition)failures.push(message);}assert(new Set(CATEGORIES.map(function(c){return c.id;})).size===CATEGORIES.length,"duplicate category id");assert(new Set(FAMILIES.map(function(f){return f.id;})).size===FAMILIES.length,"duplicate family id");assert(FAMILIES.length===51,"all 51 specified families registered");FAMILIES.forEach(function(f,familyIndex){assert(CATEGORIES.some(function(c){return c.id===f.categoryId;}),f.id+": category exists");f.levels.forEach(function(level){var signatures=new Set();for(var sample=0;sample<32;sample+=1){var seed=((familyIndex+1)*100000+level*1000+sample+1)>>>0;try{var q=generateQuestion(f.id,level,seed);assert(q.familyId===f.id,f.id+": stable family id");assert(q.prompt.title&&q.explanation,f.id+": rendering metadata");assert(checkQuestion(q.canonicalAnswer,q).correct,f.id+": canonical answer rejected L"+level+" seed "+seed);assert(!checkQuestion({},q).correct,f.id+": empty malformed answer accepted");assert(q.metadata.modelId===MODEL_ID&&q.metadata.oracleVersion===ORACLE_VERSION,f.id+": pinned model metadata");assert(q.metadata.semanticObjects&&q.metadata.modelState,f.id+": semantic metadata");signatures.add(q.structuralSignature);}catch(error){failures.push(f.id+" L"+level+" seed "+seed+": "+error.message);}}assert(signatures.size>=2,f.id+": insufficient structural variation L"+level);});});assert(rstr(radd(R(1,2),R(1,3)))==="5/6"&&rstr(rdiv(R(3),R(-6)))==="−1/2","rational landmarks");assert(rstr(det(M_([[1,2],[3,4]])))==="−2"&&rstr(det(M_([[2,0,0],[0,3,0],[0,0,4]])))==="24","determinant landmarks");var inv=inverse(M_([[1,2],[3,4]]));assert(inv.map(function(r){return r.map(rstr).join(",");}).join(";")==="−2,1;3/2,−1/2","inverse landmark");var rr=rref(M_([[0,2,4],[1,1,1]]));assert(rr.R.map(function(r){return r.map(rstr).join(",");}).join(";")==="1,0,−1;0,1,2"&&rr.piv.join()==="0,1","RREF landmark");assert(nullspace(M_([[1,1,1]])).length===2&&laNormalize("(1,1,1),(1,-1,-3)","span:3:2")===laNormalize("(1,0,-1),(0,1,2)","span:3:2"),"span equivalence landmark");assert(laNormalize("1/√2","rat")===laNormalize("√2/2","rat")&&laNormalize("2√2","rat")===laNormalize("sqrt(8)","rat")&&laNormalize("(2,-4,6)","dir:3")===laNormalize("(-1,2,-3)","dir:3")&&laNormalize("(0,0)","dir:2")===null,"answer normalization landmarks");FAMILIES.forEach(function(f){f.levels.forEach(function(level){for(var s1=0;s1<40;s1+=1){var q1=generateQuestion(f.id,level,(level*7919+s1*104729+1)>>>0);q1.fields.forEach(function(fd){if(fd.kind==="choice"){assert(fd.options.length>=2,f.id+" L"+level+": choice field "+fd.id+" has fewer than two options");assert(new Set(fd.options.map(function(o){return o.label;})).size===fd.options.length,f.id+" L"+level+": duplicate option labels");assert(fd.options.some(function(o){return o.value===fd.answer;}),f.id+" L"+level+": answer missing from options");}});}});});assert(Object.keys(TEMPLATE_CONFLICTS).length===0,"template keys reused with different English: "+Object.keys(TEMPLATE_CONFLICTS).join(","));if(TEXT.localeCode!=="en")USED_TEMPLATE_KEYS.forEach(function(k){assert(TEXT.gen&&Object.prototype.hasOwnProperty.call(TEXT.gen,k),"Swedish template "+k);});if(TEXT.localeCode!=="en"){assert(CATEGORIES.every(function(c){return Boolean(t("categories."+c.id,null));}),"localized categories complete");assert(FAMILIES.every(function(f){return Boolean(t("families."+f.id,null)&&t("familyRules."+f.id,null)&&t("familyExamples."+f.id,null));}),"localized family learn content complete");}return{ok:failures.length===0,failures:failures};}
window.LinearAlgebraApp={templateTexts:function(){return Object.assign({},TEMPLATE_EN);},templateConflicts:function(){return Object.keys(TEMPLATE_CONFLICTS);},modelId:MODEL_ID,oracleVersion:ORACLE_VERSION,categories:CATEGORIES,families:FAMILIES,generateQuestion:generateQuestion,checkQuestion:checkQuestion,oracles:{R:R,rstr:rstr,rref:rref,det:det,inverse:inverse,nullspace:nullspace,laNormalize:laNormalize,parseSurd:parseSurd,scanon:scanon}};window.runSelfTests=runSelfTests;document.addEventListener("DOMContentLoaded",init);
